import React, { useState, useEffect, useRef } from 'react';
import { BtnPrimary, BtnSecondary } from '../components/GlassButton';
import { OrbSmall } from '../components/Orb';

const PHASES = [
  { name: 'Breathe in',  seconds: 4, hint: 'Deep breath in through the nose' },
  { name: 'Hold',        seconds: 7, hint: 'Hold still'                       },
  { name: 'Breathe out', seconds: 8, hint: 'Slowly out through the mouth'     },
];
const TOTAL = 4;

// Target sizes per phase
const PHASE_SIZE = { 0: 260, 1: 260, 2: 150 };

export default function Breathing({ setPage }) {
  const [running,  setRunning]  = useState(false);
  const [done,     setDone]     = useState(false);
  const [phase,    setPhase]    = useState(0);
  const [count,    setCount]    = useState(0);
  const [cycle,    setCycle]    = useState(0);
  const [orbSize,  setOrbSize]  = useState(200);  // separate state so React actually re-renders
  const timer = useRef(null);

  const runPhase = (pi, ci) => {
    if (ci >= TOTAL) { setRunning(false); setDone(true); return; }
    setPhase(pi);
    setCycle(ci);
    // Trigger orb size change — slight delay so transition fires after state update
    setTimeout(() => setOrbSize(PHASE_SIZE[pi]), 30);
    const secs = PHASES[pi].seconds;
    setCount(secs);
    let c = secs;
    clearInterval(timer.current);
    timer.current = setInterval(() => {
      c--;
      setCount(c);
      if (c <= 0) {
        clearInterval(timer.current);
        const np = (pi + 1) % 3;
        const nc = pi === 2 ? ci + 1 : ci;
        setTimeout(() => runPhase(np, nc), 400);
      }
    }, 1000);
  };

  const start = () => { setRunning(true); setDone(false); setOrbSize(PHASE_SIZE[0]); runPhase(0, 0); };
  const reset = () => {
    clearInterval(timer.current);
    setRunning(false); setDone(false);
    setPhase(0); setCount(0); setCycle(0); setOrbSize(200);
  };
  useEffect(() => () => clearInterval(timer.current), []);

  // Transition duration matches the phase duration
  const transitionDuration = phase === 0 ? `${PHASES[0].seconds}s` : phase === 2 ? `${PHASES[2].seconds}s` : '0.6s';
  const transitionEase     = phase === 1 ? 'ease' : 'ease-in-out';

  const cur = PHASES[phase];

  const pageStyle  = { background: '#0F1C1C', minHeight: '100vh', display: 'flex', flexDirection: 'column' };
  const innerStyle = { padding: '52px 28px 160px', display: 'flex', flexDirection: 'column', justifyContent: 'space-between', flex: 1 };

  /* ── DONE ── */
  if (done) return (
    <div style={pageStyle}>
      <div style={innerStyle}>
        <OrbSmall />
        <div>
          <h2 style={{ fontSize: 40, fontWeight: 700, letterSpacing: '-0.05em', color: '#EEEAE3', marginBottom: 8 }}>
            Done<span style={{ color: '#7EC8C8' }}>.</span>
          </h2>
          <p style={{ fontSize: 14, color: 'rgba(238,234,227,0.32)', marginBottom: 36, lineHeight: 1.6 }}>
            Your nervous system has reset.
          </p>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
            <BtnPrimary onClick={() => setPage('history')}>See log →</BtnPrimary>
            <BtnSecondary onClick={reset}>Again</BtnSecondary>
          </div>
        </div>
      </div>
    </div>
  );

  /* ── ACTIVE ── */
  if (running) return (
    <div style={pageStyle}>
      <div style={innerStyle}>

        {/* Phase number indicators */}
        <div style={{ display: 'flex', justifyContent: 'center', gap: 36 }}>
          {PHASES.map((p, i) => (
            <div key={i} style={{ textAlign: 'center' }}>
              <div style={{ fontSize: 26, fontWeight: 700, letterSpacing: '-0.04em', color: phase === i ? '#EEEAE3' : 'rgba(238,234,227,0.1)', transition: 'color 0.5s' }}>
                {p.seconds}
              </div>
              <div style={{ fontSize: 9, fontWeight: 700, color: phase === i ? '#7EC8C8' : 'rgba(238,234,227,0.1)', textTransform: 'uppercase', letterSpacing: '0.08em', marginTop: 3, transition: 'color 0.5s' }}>
                {p.name.split(' ')[0]}
              </div>
            </div>
          ))}
        </div>

        {/* Breathing orb — size driven by orbSize state */}
        <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
          <div style={{
            width:  orbSize,
            height: orbSize,
            borderRadius: '50%',
            background: 'radial-gradient(circle at 38% 35%, #7EC8C8 0%, #2D6B6B 50%, #1A3A3A 100%)',
            boxShadow: `0 0 ${orbSize * 0.35}px rgba(45,107,107,0.35)`,
            display: 'flex', alignItems: 'center', justifyContent: 'center', flexDirection: 'column',
            transition: `width ${transitionDuration} ${transitionEase}, height ${transitionDuration} ${transitionEase}, box-shadow ${transitionDuration} ${transitionEase}`,
          }}>
            <div style={{ fontSize: 56, fontWeight: 700, letterSpacing: '-0.05em', color: 'rgba(255,255,255,0.95)', lineHeight: 1 }}>{count}</div>
            <div style={{ fontSize: 10, fontWeight: 600, color: 'rgba(255,255,255,0.45)', textTransform: 'uppercase', letterSpacing: '0.1em', marginTop: 5 }}>{cur.name}</div>
          </div>
        </div>

        {/* Hint */}
        <div style={{ padding: '13px 18px', borderRadius: 999, background: 'rgba(255,255,255,0.05)', boxShadow: '0 0 0 1px rgba(255,255,255,0.07)', textAlign: 'center' }}>
          <p style={{ fontSize: 13, fontWeight: 500, color: 'rgba(238,234,227,0.42)' }}>{cur.hint}</p>
          <p style={{ fontSize: 11, color: 'rgba(238,234,227,0.2)', marginTop: 5 }}>Round {cycle + 1} / {TOTAL}</p>
        </div>

      </div>
    </div>
  );

  /* ── IDLE ── */
  return (
    <div style={pageStyle}>
      <div style={{ position: 'absolute', left: '50%', transform: 'translateX(-50%)', width: 320, height: 320, top: 140, borderRadius: '50%', background: 'radial-gradient(circle at 40% 38%, rgba(126,200,200,0.28) 0%, rgba(45,107,107,0.08) 55%, transparent 75%)', filter: 'blur(30px)', pointerEvents: 'none' }} />
      <div style={innerStyle}>
        <div style={{ position: 'relative', zIndex: 1 }}>
          <div style={{ fontSize: 10, fontWeight: 700, color: 'rgba(238,234,227,0.22)', letterSpacing: '0.1em', textTransform: 'uppercase', marginBottom: 12 }}>4 – 7 – 8</div>
          <h2 style={{ fontSize: 36, fontWeight: 700, letterSpacing: '-0.05em', lineHeight: 1.04, color: '#EEEAE3' }}>Breathing<br />exercise.</h2>
        </div>
        <div style={{ display: 'flex', justifyContent: 'center', position: 'relative', zIndex: 1 }}>
          <div style={{ width: 200, height: 200, borderRadius: '50%', background: 'radial-gradient(circle at 38% 35%, #7EC8C8 0%, #2D6B6B 50%, #1A3A3A 100%)', boxShadow: '0 0 80px rgba(45,107,107,0.28)', animation: 'orbFloatFree 7s ease-in-out infinite', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            <div style={{ width: 100, height: 100, borderRadius: '50%', background: 'rgba(255,255,255,0.08)', border: '1px solid rgba(255,255,255,0.14)' }} />
          </div>
        </div>
        <div style={{ position: 'relative', zIndex: 1 }}>
          <BtnPrimary onClick={start}>Start</BtnPrimary>
        </div>
      </div>
    </div>
  );
}
